const logs = ["oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log", "pale_oak_log", "mangrove_log", "acacia_log", "jungle_log"];
const home = depot();
await move_to(home.x + 4, home.y, home.z + 4);
let log = find_block({ names: logs, max_distance: 96, any_level: true });
let walked = 0;
while (!log && walked < 3) {
  await move_to(home.x + 20 * (walked + 1), home.y, home.z + 20 * (walked + 1));
  walked += 1;
  log = find_block({ names: logs, max_distance: 96, any_level: true });
}
if (!log) {
  await move_to(home.x + 4, home.y, home.z + 4);
  return { done: false, detail: 'no tree near the depot or three walks out; going home' };
}
const chopped = await dig(log.x, log.y, log.z);
if (!chopped.ok) {
  return { done: false, detail: chopped.detail };
}
await leave_at_depot();
return { done: true, detail: 'went home, found a tree at its own level, mined a log, left the bag at the depot' };
